/**
 * The viewer's frame validators, fed the frames the server actually sends.
 *
 * Every assertion here runs against `__fixtures__/api-frames.json`, which is
 * generated by `scripts/dump_viewer_frames.py` from `headsup.api.frames` --
 * the only producer of viewer frames that has ever existed. Nothing in this
 * file hand-writes a frame, on purpose: a hand-written one can agree with a
 * validator and disagree with the server, which is exactly the failure this
 * file exists to prevent.
 *
 * The bug: `records.js` read every pipeline frame out of a nested
 * `{type: 'hazard', hazard: {...}}` envelope and under field names
 * (`sentinel`, `vehicles`, `decision`, an `action` object) the server does
 * not use. It sends flat frames with different spellings. Because
 * `viz/mock_stream.py` only ever emitted `telemetry` and `advisory`, no test
 * on either side ever put a real pipeline frame through a validator, so all
 * six returned null for the life of the build and the agent rail, the stage
 * cards and the status strip stayed dark on a pipeline that was working.
 *
 * `tests/unit/test_viewer_frame_fixture.py` regenerates the fixture and
 * fails when it drifts, so a change to a frame's shape breaks the Python
 * suite and this one together, in the commit that makes it.
 * @module layers/headsup/records.contract.test
 */

import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import test from 'node:test';

import {
  compileFromAdvisory,
  normalizeAckFrame,
  normalizeAdvisoryFeature,
  normalizeAssistFrame,
  normalizeCandidateFrame,
  normalizeCountersFrame,
  normalizeHazardFrame,
  normalizeProposalFrame,
  normalizeTelemetryFrame,
  normalizeVerdictFrame,
} from './records.js';

const FRAMES = JSON.parse(
  readFileSync(
    fileURLToPath(new URL('./__fixtures__/api-frames.json', import.meta.url)),
    'utf8',
  ),
);

/** The validator each frame kind is routed to by `source.js`. */
const VALIDATORS = Object.freeze({
  candidate: normalizeCandidateFrame,
  hazard: normalizeHazardFrame,
  proposal: normalizeProposalFrame,
  verdict: normalizeVerdictFrame,
  ack: normalizeAckFrame,
  counters: normalizeCountersFrame,
  assist: normalizeAssistFrame,
});

test('every frame the server sends survives its validator', () => {
  // The whole bug in one assertion: before the fix, six of these were null.
  for (const [kind, validate] of Object.entries(VALIDATORS)) {
    const frame = FRAMES[kind];
    assert.ok(frame, `fixture is missing a ${kind} frame`);
    assert.notEqual(
      validate(frame),
      null,
      `the server's ${kind} frame was rejected by its validator`,
    );
  }
});

test('an advisory feature still reads, since that path was never broken', () => {
  assert.notEqual(normalizeAdvisoryFeature(FRAMES.advisory.feature), null);
});

test('a candidate carries what the SENTINELS row and its card draw', () => {
  const candidate = normalizeCandidateFrame(FRAMES.candidate);
  // `hazardClass` is the row's value, `sentinel` names who read it, and the
  // evidence rows are what the FEEDS chips are counted from. A candidate
  // missing any of these lights a row that then says nothing.
  assert.equal(candidate.id, FRAMES.candidate.id);
  assert.equal(candidate.hazardClass, FRAMES.candidate.class);
  assert.equal(candidate.sentinel, FRAMES.candidate.detected_by);
  assert.ok(candidate.evidence.length > 0, 'no evidence rows, so no feed chips');
  assert.deepEqual(
    candidate.evidence.map((row) => row.source).sort(),
    [...new Set(FRAMES.candidate.sources)].sort(),
    'the chips must name the feeds the frame cites, and only those',
  );
});

test('a fused hazard carries the confidence the FUSION row shows', () => {
  const hazard = normalizeHazardFrame(FRAMES.hazard);
  assert.equal(hazard.id, FRAMES.hazard.id);
  assert.equal(hazard.hazardClass, FRAMES.hazard.class);
  // The one number fusion exists to produce. Null here renders an empty row.
  assert.equal(typeof hazard.confidence, 'number');
  assert.deepEqual(hazard.candidateIds, FRAMES.hazard.candidate_ids);
});

test('a proposal reads its action from a bare string', () => {
  // The server sends `action: 'NO_ENTRY'`. The old validator required
  // `action: {type: 'NO_ENTRY'}` and dropped the frame when it got a string.
  const proposal = normalizeProposalFrame(FRAMES.proposal);
  assert.equal(typeof FRAMES.proposal.action, 'string');
  assert.equal(proposal.action, FRAMES.proposal.action);
  assert.equal(proposal.hazardId, FRAMES.proposal.hazard_id);
});

test('a proposal naming an action outside the playbook is refused', () => {
  // The vocabulary rule is a guardrail, not a display detail: the rail must
  // never render an action a proposer invented. Loosening the envelope must
  // not have loosened this.
  assert.equal(
    normalizeProposalFrame({ ...FRAMES.proposal, action: 'OPEN_THE_ROAD' }),
    null,
  );
});

test("a verdict reads the decision out of the field named `verdict`", () => {
  // The collision that makes this frame the awkward one: the flat frame's
  // decision field has the same name as the nested envelope would. Unwrap
  // naively and `verdict` becomes the string 'APPROVE' instead of an object.
  const verdict = normalizeVerdictFrame(FRAMES.verdict);
  assert.equal(verdict.decision, FRAMES.verdict.verdict);
  assert.equal(verdict.proposalId, FRAMES.verdict.proposal_id);
});

test('an unreadable verdict escalates rather than approving', () => {
  // The safe reading of an answer we cannot parse is that a person still has
  // to look. Unchanged by the rewrite, and asserted here because the rewrite
  // touched the branch that decides it.
  assert.equal(
    normalizeVerdictFrame({ ...FRAMES.verdict, verdict: 'SOMETHING_NEW' })
      .decision,
    'ESCALATE',
  );
});

test('an ack reads the rerouted count and who answered', () => {
  const ack = normalizeAckFrame(FRAMES.ack);
  assert.equal(ack.operator, FRAMES.ack.operator);
  assert.equal(ack.status, FRAMES.ack.status);
  assert.equal(ack.vehicles, FRAMES.ack.vehicles_rerouted);
  assert.equal(ack.advisoryId, FRAMES.ack.advisory_id);
});

test('an ack with an unknown status is read as a refusal', () => {
  assert.equal(
    normalizeAckFrame({ ...FRAMES.ack, status: 'MAYBE' }).status,
    'DECLINED',
  );
});

test('counters read both cohorts out of the headline block', () => {
  const counters = normalizeCountersFrame(FRAMES.counters);
  const headline = FRAMES.counters.headline;
  assert.equal(counters.hazardEntries.live, headline.live.hazard_entries);
  assert.equal(counters.hazardEntries.ghost, headline.ghost.hazard_entries);
  assert.equal(counters.assistQueue.live, headline.live.assist_queue_depth);
  assert.equal(counters.assistQueue.ghost, headline.ghost.assist_queue_depth);
});

test('a run with no ghost cohort still reports the live one', () => {
  // A ghost fleet is optional. Blanking the live column because the ghost
  // column is absent would hide a number the page actually has.
  const live = { ...FRAMES.counters.headline.live };
  const counters = normalizeCountersFrame({
    ...FRAMES.counters,
    headline: { live },
  });
  assert.equal(counters.hazardEntries.live, live.hazard_entries);
  assert.equal(counters.hazardEntries.ghost, 0);
});

test('the older nested envelope is still readable', () => {
  // Kept so a publisher speaking the earlier draft is visible rather than
  // silently dropped -- the failure mode this whole file exists to close.
  const { type, ...body } = FRAMES.hazard;
  assert.notEqual(normalizeHazardFrame({ type, hazard: body }), null);
});

test('a published advisory implies the compiler result that signed it', () => {
  // There is no `compile` frame on the wire, so without this the COMPILER
  // row stays dark on a run that published an advisory -- which reads as
  // "the gate did not run" rather than "the gate ran, and here is what it
  // produced".
  const compiled = compileFromAdvisory(FRAMES.advisory);
  assert.equal(compiled.status, 'SIGNED');
  assert.equal(compiled.advisoryId, FRAMES.advisory.id);
  assert.equal(compiled.proposalId, FRAMES.advisory.proposal_id);
  assert.equal(compiled.signatureVerified, FRAMES.advisory.signature_valid);
  // Nothing that reached the socket is still waiting on a person.
  assert.equal(compiled.twoKey, false);
  assert.equal(compiled.derived, true);
});

test('a derived compile passes the signature check through, never assumes it', () => {
  const unverified = compileFromAdvisory({
    ...FRAMES.advisory,
    signature_valid: false,
  });
  // An advisory that did not verify still shows, marked. Reporting it as
  // verified because it arrived would be the one lie this card cannot tell.
  assert.equal(unverified.signatureVerified, false);
  assert.equal(unverified.status, 'SIGNED');
});

test('only an advisory frame yields a compile record', () => {
  assert.equal(compileFromAdvisory(FRAMES.hazard), null);
  assert.equal(compileFromAdvisory({ type: 'advisory' }), null);
});

test('the control fleet arrives as its own frame type and is kept', () => {
  // The bug this pins: the server sends the ghost cohort as `ghost_telemetry`
  // (api/runner.py rewrites the type), and `VehicleState` has no per-vehicle
  // `ghost` field, so a validator that only accepts `telemetry` and only reads
  // `vehicle.ghost` discarded the entire control fleet. The counters reported a
  // ghost column while the map showed none -- and the comparison between the
  // advised and unadvised fleet is the demo's whole claim.
  const live = {
    type: 'telemetry',
    tick: 1,
    vehicles: [{ id: 'v-1', op: 'op_a', lon: -97.74, lat: 30.27, heading: 90 }],
  };
  const ghost = { ...live, type: 'ghost_telemetry' };

  const liveRows = normalizeTelemetryFrame(live);
  assert.notEqual(liveRows, null);
  assert.equal(liveRows[0].ghost, false);

  const ghostRows = normalizeTelemetryFrame(ghost);
  assert.notEqual(ghostRows, null, 'the control fleet frame was rejected');
  assert.equal(ghostRows[0].ghost, true, 'control vehicles must read as ghost');
});

test('a frame-level ghost flag marks the cohort too', () => {
  // `Telemetry.ghost` is in the contract even when the type is not rewritten.
  const rows = normalizeTelemetryFrame({
    type: 'telemetry',
    ghost: true,
    vehicles: [{ id: 'v-2', op: 'op_b', lon: -97.74, lat: 30.27 }],
  });
  assert.equal(rows[0].ghost, true);
});

test('a deflected vehicle names the advisory that moved it', () => {
  // `rerouted_by` is what the deflection trail is drawn from and what the
  // fleet's rerouted count is derived from. It was absent from VehicleState
  // for the whole build, so the readout sat at 0 in every scenario and the
  // trail could never draw -- the simulator rerouted and the viewer had no
  // way to say so.
  const rows = normalizeTelemetryFrame({
    type: 'telemetry',
    tick: 2,
    vehicles: [
      { id: 'v-3', op: 'op_a', lon: -97.74, lat: 30.27, rerouted_by: 'adv_1' },
      { id: 'v-4', op: 'op_a', lon: -97.73, lat: 30.27 },
    ],
  });
  assert.equal(rows[0].reroutedBy, 'adv_1');
  assert.equal(rows[1].reroutedBy, null, 'an undeflected vehicle claims nothing');
});

test('a frame of the wrong kind is refused by every validator', () => {
  for (const [kind, validate] of Object.entries(VALIDATORS))
    assert.equal(
      validate({ ...FRAMES[kind], type: 'something_else' }),
      null,
      `${kind} validated a frame that was not its own`,
    );
});
